import json
from pathlib import Path
p=Path('verification/state-guides/research/additional-b.json')
d={'schema_version':1,'created_on':'2026-10-16','language':'en','publication_status':'LOCAL_DRAFT_NOT_APPROVED_NOT_IN_SITEMAP','editorial_policy':'Official sources support regulatory statements. General accounting practices are identified separately. Qualified review pending.','pilots':[]}
if p.exists(): d=json.loads(p.read_text(encoding='utf-8'))
def add(state,code,desc,summary,rows,sources,gaps):
 item={'state':state,'code':code,'slug':state.lower().replace(' ','-')+'-bookkeeping','title':state+' Bookkeeping','description':desc,'summary':summary,'verified_on':'2026-10-16','status':'Local Draft Qualified Review Pending','notice':'General bookkeeping information. Last reviewed October 16, 2026. Confirm treatment with a qualified professional using current instructions and business facts.','sections':[{'heading':h,'source_ids':[code+str(i) for i in ids],'paragraphs':ps} for h,ids,ps in rows],'sources':[{'id':code+str(i+1),'title':t,'url':u,'claims':c,'checked_on':'2026-10-16','verification':'Official content inspected through web retrieval or current indexed official excerpts.'} for i,(t,u,c) in enumerate(sources)],'review_gaps':gaps,'quality_review':{'reviewed_on':'2026-10-16','state_specificity':summary,'topic_coverage':['Sales and use tax or applicable alternative','Employer records','Accounts payable and vendor evidence','Income and expenses','Monthly financial reporting','Year end handoff','Retention by verified record type','Distinct hypothetical example'],'source_bounds':'Section references identify regulatory support. General accounting recommendations are practice suggestions, not additional state mandates.','originality':'Individually composed state discussion and hypothetical business scenario.','approval_status':'Owner approval and qualified factual review pending.'}}
 d['pilots']=[x for x in d['pilots'] if x['code']!=code]+[item]
 p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
add('Maine','ME','Maine bookkeeping for the 2026 service tax transition, seasonal payroll, vendor evidence and six year sales records.','Maine businesses need a clear boundary between legacy service provider tax records and sales tax activity beginning in 2026.',[
('The 2026 Service Tax Transition',[1],['Maine repealed the Service Provider Tax effective January 1, 2026 and moved the affected services into sales and use tax. The official bulletin identifies fabrication, telecommunications and related services among the affected activities. Retain the service description and transaction date so the preparer can distinguish a current sale from an amendment to a legacy period.','As a practical accounting control, archive the old tax mapping before changing invoice settings. A business migrating fabrication receipts should be able to reproduce its former returns and explain why current invoices use a different tax account. Do not assume an old agency navigation label establishes current tax treatment.']),
('Sales And Purchase Documentation',[2],['Maine sales records include purchase price information for property and taxable services used in Maine. Attach vendor invoices, shipping evidence and exemption support to the relevant period. A resale purchase and a tool consumed in the business belong on different review paths.','For accounts payable, record supplier credits against the original bill and preserve the reason for the adjustment. Keep delivery charges and separately stated taxes visible. A card charge proves payment but usually does not describe the item well enough to support a tax classification.']),
('Seasonal Payroll And Employer Accounts',[3],['An active Maine withholding account requires quarterly returns even when there were no employees or no withholding. The current agency FAQ specifically says there is no seasonal withholding filing frequency. Maintain a calendar linked to the active account rather than assuming a winter shutdown ends reporting.','Reconcile approved hours, wages, deductions, payments and filed payroll totals. As a general control, retain the payroll provider export and payment acknowledgment together; keep unemployment and other employer obligations on distinct schedules for specialist review.']),
('Monthly Reports And Income Evidence',[],['A seasonal business should compare current profit and loss results with both the prior month and the corresponding operating season. Reconcile cash, cards, deposits and loans before explaining the results. Customer advance payments and owner funding should each retain their original description.','Review unpaid vendor bills and the purchase tax question list during the close. An offseason cash balance may include customer deposits needed for next season, so explain those balances beside the balance sheet instead of treating every bank dollar as available profit.']),
('Hypothetical Fabrication Shop',[1],['Hypothetical example: a Maine metal shop completes a fabricated railing in 2026 and later discovers an invoice correction relating to a 2025 project. The bookkeeper separates the two transaction histories, saves the signed orders and completion evidence, and gives the preparer both tax account mappings. The example establishes no rate, exemption or reporting period conclusion.']),
('Year End And Retention',[2,4],['Deliver annual sales totals by activity, legacy corrections, inventory counts, asset invoices, payroll reconciliations and unresolved purchase questions to the tax preparer. Include a written explanation of any conversion between accounting systems so beginning balances can be traced.','The current Maine sales publication requires six year retention and specifically preserves legacy Service Provider Tax records for six years after generation despite repeal. Title 36 section 135 separately ties income tax records under Part 8 to applicable federal rules; it does not give every record one six year destruction date. Preserve records subject to an audit or other hold and obtain a separate employer retention schedule.'])],[('Maine 2025 Legislative Bulletin 115','https://www.maine.gov/revenue/sites/maine.gov.revenue/files/inline-files/GIB%20115_FINAL_2025_10_17_0.pdf',['SPT repeal and affected services entering sales and use tax January 1, 2026.']),('Maine Sales And Use Tax Business Publication December 2025','https://www.maine.gov/revenue/sites/maine.gov.revenue/files/inline-files/Business%20Guide%20for%20December%202025%20FINAL.pdf',['Sales and purchase documentation and six year sales and legacy SPT preservation.']),('Maine Income Tax Withholding FAQ','https://www.maine.gov/revenue/faq/income-tax-withholding',['Quarterly active account reporting including seasonal zero periods.']),('Maine Title 36 Section 135','https://legislature.maine.gov/statutes/36/title36sec135.html',['Record security and access, six year general tax rule and federal alignment exceptions for income taxes.'])],['Individual service classification and employer retention periods require specialist review. No rate or payment deadline asserted.'])
add('Maryland','MD','Maryland bookkeeping for sales evidence, state and local withholding information, vendor payments and separate retention clocks.','Maryland sales records and employer withholding records have different preservation periods, and payroll needs accurate residence information.',[
('Sales And Use Tax Evidence',[1],['Maryland requires records pertaining to sales and purchases, including information needed to determine sales and use tax. Organize original sales, exempt sales and purchase invoices so a reviewer can trace return totals to transactions. Keep a certificate with the customer relationship and preserve the evidence supporting its use.','As an accounts payable practice, flag equipment and supply invoices without tax, preserve their use location and send the facts for use tax review. Avoid deciding tax solely from a vendor name or a payment description.']),
('Employer Withholding And Local Information',[2,3],['The Maryland employer publication covers state and local withholding and requires wage dates and amounts, taxes withheld, employee identity, employment periods and exemption certificates. Preserve residence changes with their effective dates so the payroll professional can apply the appropriate instructions.','The Comptroller requires withheld sums to appear in a ledger account identifying the state tax. Reconcile that account with payroll registers, payments and return acknowledgments. The annual MW508 reconciliation needs wage and withholding detail, not simply the annual cash withdrawn by the payroll provider.']),
('Vendor Bills And Income Classification',[],['A Maryland professional practice can receive insurer settlements, direct customer payments, loan proceeds and owner contributions in one account. Identify the origin of each deposit before posting it. Preserve adjustment explanations when a settlement differs from the customer invoice.','Match vendor bills to approval, receipt and payment. Track equipment financing separately from the equipment cost, and separate principal from financing charges in the debt schedule. These are general bookkeeping practices; tax deductibility and capitalization decisions remain with the preparer.']),
('Monthly Reconciliation And Reporting',[],['Close the bank, card, customer and vendor ledgers before delivering a profit and loss statement and balance sheet. Investigate old credits and outstanding checks with the owner. A clean bank reconciliation alone does not establish that customer balances or tax liabilities are correct.','For payroll, compare quarterly wages with year to date records after each close and annotate residence changes affecting local withholding. Maintain a notice log so a payment posted under the wrong account does not become a recurring unexplained adjustment.']),
('Hypothetical Employee Move',[2],['Hypothetical example: a Maryland design studio employee changes residence during the year. The bookkeeper obtains the updated withholding certificate and effective date, sends the change through payroll review and preserves the adjustment report. The studio then reconciles the annual wage record to the corrected payroll totals. The example assumes no local rate or retroactive adjustment entitlement.']),
('Year End And Record Retention',[1,2],['Prepare the tax handoff with reconciled statements, receivable adjustments, vendor totals, asset and debt schedules, sales returns and the annual payroll reconciliation. Give the preparer a separate list of uncertain exemptions and expenses with missing support.','Maryland Business Tax Tip 2 states four years for sales and purchase records. The 2026 employer publication states at least three years after the related tax became due or was paid, whichever is later, for withholding records. Those are distinct rules; broader employment, federal and property basis obligations may require longer preservation.'])],[('Maryland Business Tax Tip 2 Sales And Use Records','https://www.marylandcomptroller.gov/content/dam/mdcomp/tax/legal-publications/tips/business/bustip2.pdf',['Sales and purchases documentation and four year retention.']),('Maryland 2026 Employer Withholding Publication','https://www.marylandcomptroller.gov/content/dam/mdcomp/tax/instructions/withholding/2026/withholding-guide.pdf',['State and local withholding, required employer records, three year due or paid retention clock, MW508 reconciliation.']),('Maryland Employer Withholding','https://services.marylandcomptroller.gov/taxes/en/employer-withholding?id=kb_article_view&sysparm_article=KB0010017',['Separate withholding ledger account and annual reconciliation.'])],['Unemployment insurance, leave programs, labor records and industry specific taxes need separate applicability review.'])
add('Massachusetts','MA','Massachusetts bookkeeping for sales detail, work location payroll evidence, vendor records and tax retention exceptions.','Massachusetts records need to support both taxable and exempt activity, with special attention to the work location evidence behind nonresident withholding.',[
('Sales And Use Tax Records',[1,2],['Massachusetts vendors must keep complete sales and purchase records whether transactions are taxable or not. Preserve invoices, register details and the basis for exemptions. Keep sale price, tax, refund and payment processor fees separately identifiable when reconciling settlements.','For vendor purchases, retain item descriptions and destination information for use tax review. A bill for a computer, materials and a service should preserve each component so the preparer can resolve treatment from the actual purchase. Keep disputed bills and supplier credit memoranda linked.']),
('Payroll And Work Location Support',[2,3],['The withholding publication requires employee identity, wage dates and amounts, withholding certificates, wage statements and filed returns. For a nonresident whose withholding depends on workdays within Massachusetts, the record retention regulation calls for payroll and attendance records establishing location or documentation of an allowed alternative method.','As a bookkeeping control, reconcile payroll liabilities separately from net pay and employer costs. If an employee changes remote work arrangements, record the effective date and preserve the supporting statement for payroll review. Assess unemployment, paid leave and other employer programs separately.']),
('Income And Payables Evidence',[],['Keep project deposits, invoices, retainers and collection adjustments in a customer ledger that explains what has been earned under the agreed accounting basis. A bank deposit from a client may settle several invoices, so retain the remittance detail. Owner loans should remain identifiable through their agreements.','For purchases, connect the approved bill to receiving evidence and payment. Save asset installation and improvement documents with the original purchase record. Review personal charges and reimbursements with the owner before closing the expense accounts.']),
('Monthly Financial Review',[],['A useful monthly package includes reconciled cash, customer aging, unpaid bills, a profit and loss statement and a balance sheet. Explain any material difference between invoiced revenue and cash collected. Review unearned deposits and unfinished work under the accounting method chosen with the preparer.','Keep sales tax and payroll reconciliations alongside the package, each showing beginning liability, new activity, payments and adjustments. Confirm that return corrections appear in the ledger and that old credits have documented owners and next actions.']),
('Hypothetical Visiting Designer',[2],['Hypothetical example: a New Hampshire resident employed by a Massachusetts studio divides work between home and the studio. The bookkeeper preserves dated work location records and any signed certification used by payroll. A later correction remains attached to the original wage report. This scenario does not decide withholding eligibility or estimate the number of taxable days.']),
('Year End And Preservation Clocks',[1,2,3],['At year end, assemble the sales reconciliation, wage statement support, asset rollforward, debt confirmations and customer deposit schedule. Preserve current and amended filings with their submission evidence so the preparer can connect the books to the tax history.','Sales and withholding publications generally specify at least three years after the return was filed or due, whichever is later. The regulation contains exceptions, including records supporting future property dispositions, which remain needed through three years after the disposition year return was due or filed, whichever is later. Fraud, missing returns, substantial understatements and proceedings can extend the relevant period.'])],[('Massachusetts Sales And Use Tax','https://www.mass.gov/guides/sales-and-use-tax',['Sales documentation and ordinary three year retention with exceptions.']),('Massachusetts Regulation 830 CMR 62C.25.1','https://www.mass.gov/regulations/830-CMR-62c251-record-retention',['Tax records, nonresident location evidence, ordinary retention and property disposition exception.']),('Massachusetts Withholding Tax Publication','https://www.mass.gov/info-details/withholding-tax-guide',['Required payroll withholding documents and three year filed or due retention period.'])],['Paid leave, unemployment and industry rules need independent applicability and retention review.'])
add('Michigan','MI','Michigan bookkeeping for exemption evidence, use tax purchases, combined tax reporting and annual reconciliations.','Michigan combined sales, use and withholding reporting makes separate ledger schedules essential even when several taxes share a return.',[
('Sales And Exemption Evidence',[1,2],['Michigan Treasury requires sellers to maintain accurate sales records. Its exemption bulletin identifies the purchaser, transaction date, item, exemption type and sales amount among the required information, with registration details for applicable resale or lease claims. Preserve this support alongside the underlying invoice.','Purchases from vendors that do not collect Michigan tax can need use tax review. Maintain a purchase register showing the item, use location, tax paid elsewhere and the preparer decision. A missing tax line is a question to resolve, not permission to omit the purchase from review.']),
('Employer Withholding And Reporting',[3,4],['Michigan generally connects employer withholding registration to the federal employer withholding requirement. Preserve employee certificates, wage details and actual work locations for payroll review, especially where reciprocity or remote work is involved. Worker classification needs facts about the relationship beyond a vendor invoice.','Michigan reports sales, use and withholding through its reporting system, while unemployment insurance belongs to the Unemployment Insurance Agency. Maintain distinct liability accounts and payment support. A single portal payment should be allocated to the relevant tax schedules rather than posted entirely to payroll expense.']),
('Accounts Payable And Income Controls',[],['A small manufacturer should distinguish raw materials, machinery, repair parts and general office purchases in its vendor files. The accounting description should explain how the item is used so a preparer can evaluate a claimed exemption. Retain the original bill when a supplier issues a correction.','Customer receipts should connect to invoices, deposits and credit memoranda. Record loan proceeds and owner funding separately from operating income, and preserve asset purchase and financing agreements together without combining debt principal and expense.']),
('Monthly Close And Annual Return Bridge',[2],['Treasury assigns filing frequency and requires an annual return regardless of the periodic schedule. As a practical monthly control, maintain year to date reconciliations for each applicable tax so the annual totals can be reproduced from the books.','Review bank and card reconciliations, vendor aging, stock adjustments and customer balances before issuing financial statements. Explain timing differences between tax payments and ledger liabilities. Reconcile sales reported by the selling platform with processor deposits and any marketplace collection records.']),
('Hypothetical Resale Certificate Change',[1],['Hypothetical example: a Michigan parts distributor changes customer software and discovers that an exempt customer flag migrated without its supporting certificate. The bookkeeper retrieves the purchaser information and original exemption evidence, links it to affected invoices and sends unresolved transactions to the preparer. A software flag alone is not treated as substantiation.']),
('Year End Records And Retention',[1,2],['The year end package should connect annual sales, purchase use tax and withholding totals to the ledger. Include inventory count adjustments, asset disposals, wage reporting confirmations, debts and unresolved exemption questions. Preserve the version of the tax mapping used for each period.','Treasury exemption bulletin 2024 11 requires substantiating data for an exempt sale for at least four years from the date tax was due on that transaction. Apply that verified clock to exemption evidence. It is not a universal four year rule for payroll, personnel, federal income tax or property basis records; establish separate schedules before disposing of them.'])],[('Michigan Revenue Administrative Bulletin 2024 11','https://www.michigan.gov/taxes/rep-legal/rab/2024-revenue-administrative-bulletins/revenue-administrative-bulletin-2024-11',['Exemption evidence and four years from transaction tax due date.']),('Michigan Sales And Use Taxes','https://www.michigan.gov/taxes/business-taxes/sales-use-tax',['Purchase use tax, assigned filing frequency and annual return.']),('Michigan Withholding Tax FAQs','https://www.michigan.gov/taxes/business-taxes/withholding/withholding-tax-faqs',['Employer withholding registration and relationship to federal withholding.']),('Michigan Employer Unemployment Insurance','https://www.michigan.gov/leo/bureaus-agencies/uia/employers/about-taxes-and-ui',['Separate unemployment employer program.'])],['Payroll retention, reciprocity, industrial processing exemptions and marketplace facts need individualized review.'])
print([(x['code'],sum(len(p.split()) for s in x['sections'] for p in s['paragraphs'])) for x in d['pilots']])
